        "key": "premium_impact",
        "evidence_id": "metric:fixed_exposure_portfolio",
        "field": "value"
      }
    ],
    "related_deterministic_finding_ids": []
  },
  "interpretations": [
    {
      "title": "Weight availability and interpretation",
      "explanation": "Both exposure-weighted rate and fixed-exposure premium-impact measures are available. Current-premium weighting is also reported as available and matches the fixed-exposure premium-impact measure; the stated assumption says it requires comparable valid premiums.",
      "recommended_action": "Confirm that the premium data used for current-premium weighting are comparable and valid, and review the fixed-exposure and unchanged-coverage assumptions.",
      "evidence_refs": [
        "metric:exposure_weighted",
        "metric:fixed_exposure_portfolio",
        "metric:current_premium_weighted",
        "config:calculation"
      ],
